import{_ as a,c as t,o as s,ah as i}from"./chunks/framework.CdwlI3v5.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"_layout":"writeup","ctf":"ISITDTU Quals 2018","chal":"Simple RSA","flag":"ISITDTU{f6b2b7472273aacf803ecfe93607a914}","points":534,"category":"crypto"},"headers":[],"relativePath":"writeups/2018/ISITDTU Quals 2018/Simple RSA/2018-07-28-Simple RSA.md","filePath":"writeups/2018/ISITDTU Quals 2018/Simple RSA/2018-07-28-Simple RSA.md"}'),p={name:"writeups/2018/ISITDTU Quals 2018/Simple RSA/2018-07-28-Simple RSA.md"};function o(n,e,r,c,l,d){return s(),t("div",null,[...e[0]||(e[0]=[i(`<blockquote><p>We are given a <a href="./simple_rsa.py">simple_rsa.py</a></p></blockquote><p>This is just a typical RSA factorization attack, just fancier and forces you to either be amazing at getting code from github and/or know how RSA works</p><p>First we notice that N isn&#39;t just made from 2 primes, it actually is 4 primes multiplied together. These 4 primes satisfy the relation</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>p2=10p1+c1</span></span>
<span class="line"><span>p3=10p2+c2</span></span>
<span class="line"><span>p4=10p3+c3</span></span></code></pre></div><p>where <code>c1,2,3</code> are some small constants so that <code>p2,3,4</code> are prime and <code>p1</code> is 251 bits long.</p><h2 id="factoring" tabindex="-1">Factoring <a class="header-anchor" href="#factoring" aria-label="Permalink to “Factoring”">​</a></h2><p>Using <code>p1*p4≈1000p1^2=(100p1)*(10p1)≈p2*p3</code>, we see that this is a basic setup for fermat factorization, thus I just went to github to grab some <a href="./fermat.py">fermat factorization code</a> to find <code>p1*p4</code> and <code>p2*p3</code></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>p1*p4=24556891073418994576751524607635760117996811894972202516187698043229292302109114380884247668494990605537878648233446996676371523211326680052450374168750431</span></span>
<span class="line"><span>p2*p3=24556891073418994576751524607635760117996811894972202516187698043229292302185592473522031534536176858756163591603824821794497153855658790721132779232081801</span></span></code></pre></div><p>We know that p4≈1000p1 and p3≈10p2, thus we can use coppersmith attack on it. MeePwn recently had a similar challenge where 7331q≈1337p but the last 512 bits are scrambled. For here, after some approximation using Daniel Goldston, János Pintz and Cem Yıldırım&#39;s estimation of prime gaps(2007), I chose the error to be 17 bits, then I used p4&#39;s code, <a href="./coppersmith.sage">modified a little</a>, ran on <a href="http://sagecell.sagemath.org/" target="_blank" rel="noreferrer">sagecell</a>, and got all 4 <a href="primes.txt">primes</a>.</p><h2 id="decrypting-message" tabindex="-1">Decrypting message <a class="header-anchor" href="#decrypting-message" aria-label="Permalink to “Decrypting message”">​</a></h2><p>Ok so we got all 4 primes, how do we decrypt?</p><p>We know that <code>m^e mod N=c</code>, thus we need to find a number d such that <code>m^(ed) mod N=m=c^d</code></p><p>Using Euler&#39;s theorem, we know that <code>ed mod φ(N)=1</code>, and since N is just a product of 4 primes, <code>φ(n)=(p1-1)(p2-1)(p3-1)(p4-1)</code></p><p>With this we can easily <a href="./decrypt.py">decrypt</a> and get the flag</p><p>p.s. I believe that <code>p1</code> is 251 bits long to emulate 512-bit RSA. Notice how <code>N=p1*p2*p3*p4≈(1000p1^2)^2</code>, <code>1000p1^2</code> is likely to be 512 bits long(<code>log2(10)^3+251*3=511.965784...</code>)</p>`,15)])])}const g=a(p,[["render",o]]);export{m as __pageData,g as default};
